def validate_mandatory(self):
	mandatory = ["warehouse", "posting_date", "voucher_type", "voucher_no", "company"]
	for k in mandatory:
		if not self.get(k):
			frappe.throw(_("{0} is required").format(_(self.meta.get_label(k))))

	if self.voucher_type != "Stock Reconciliation" and not self.actual_qty:
		frappe.throw(_("Actual Qty is mandatory"))

@api.depends('inventory_quantity', 'quantity', 'product_id')
def _compute_is_outdated(self):
    self.is_outdated = False
    for quant in self:
        if quant.product_id and quant.uom_id.compare(quant.inventory_quantity - quant.inventory_diff_quantity, quant.quantity) and quant.inventory_quantity_set:
            quant.is_outdated = True

@classmethod
def check_origin(cls, moves, types=None):
    pool = Pool()
    Warning = pool.get('res.user.warning')
    if types is None:
        types = cls.check_origin_types()
    if not types:
        return

    def no_origin(move):
        return ((move.from_location.type in types)
            ^ (move.to_location.type in types)
            and not move.origin)
    moves = sorted(filter(no_origin, moves))
    if moves:
        names = ', '.join(m.rec_name for m in moves[:5])
        if len(moves) > 5:
            names += '...'
        warning_name = Warning.format('done', moves)
        if Warning.check(warning_name):
            raise MoveOriginWarning(warning_name,
                gettext('stock.msg_move_no_origin',
                    moves=names))

protected void checkBeforeUpdatingQties(StockMoveLine stockMoveLine, BigDecimal qty)
    throws AxelorException {
  if (stockMoveLine == null) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(SupplychainExceptionMessage.SALE_ORDER_LINE_NO_STOCK_MOVE));
  }
  if (qty.signum() < 0) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(SupplychainExceptionMessage.SALE_ORDER_LINE_RESERVATION_QTY_NEGATIVE));
  }
}

