def get_stock_reco_qty_shift(kwargs):
	stock_reco_qty_shift = 0
	if kwargs.get("is_adjustment_entry") and not kwargs.get("is_cancelled"):
		# an adjustment entry moves stock rather than setting a balance, which the reset of an
		# Adjustment Entry does in several entries of one voucher
		return flt(kwargs.actual_qty)

	if kwargs.get("is_cancelled"):
		if kwargs.get("previous_qty_after_transaction"):
			if kwargs.get("serial_and_batch_bundle"):
				return kwargs.get("previous_qty_after_transaction")

			# get qty (balance) that was set at submission
			last_balance = kwargs.get("previous_qty_after_transaction")
			stock_reco_qty_shift = flt(kwargs.qty_after_transaction) - flt(last_balance)
		else:
			stock_reco_qty_shift = flt(kwargs.actual_qty)

	elif kwargs.get("serial_and_batch_bundle"):
		stock_reco_qty_shift = flt(kwargs.actual_qty)

	else:
		# reco is being submitted
		last_balance = get_previous_sle_of_current_voucher(kwargs, "<=", exclude_current_voucher=True).get(
			"qty_after_transaction"
		)

		if last_balance is not None:
			stock_reco_qty_shift = flt(kwargs.qty_after_transaction) - flt(last_balance)
		else:
			stock_reco_qty_shift = kwargs.qty_after_transaction

	return stock_reco_qty_shift

@api.model
def _clean_reservations(self):
    reserved_quants = self.env['stock.quant']._read_group(
        [('reserved_quantity', '!=', 0)],
        ['product_id', 'location_id', 'lot_id', 'package_id', 'owner_id'],
        ['reserved_quantity:sum', 'id:recordset'],
    )
    reserved_move_lines = self.env['stock.move.line']._read_group(
        [
            ('state', 'in', ['assigned', 'partially_available', 'waiting', 'confirmed']),
            ('quantity_product_uom', '!=', 0),
            ('product_id.is_storable', '=', True),
        ],
        ['product_id', 'location_id', 'lot_id', 'package_id', 'owner_id'],
        ['quantity_product_uom:sum'],
    )
    reserved_move_lines = {
        (product, location, lot, package, owner): reserved_quantity
        for product, location, lot, package, owner, reserved_quantity in reserved_move_lines
    }
    for product, location, lot, package, owner, reserved_quantity, quants in reserved_quants:
        ml_reserved_qty = reserved_move_lines.get((product, location, lot, package, owner), 0)
        if location.should_bypass_reservation():
            quants._update_reserved_quantity(product, location, -reserved_quantity, lot_id=lot, package_id=package, owner_id=owner)
        elif product.uom_id.compare(reserved_quantity, ml_reserved_qty) != 0:
            quants._update_reserved_quantity(product, location, ml_reserved_qty - reserved_quantity, lot_id=lot, package_id=package, owner_id=owner)
        if ml_reserved_qty:
            del reserved_move_lines[(product, location, lot, package, owner)]

    for (product, location, lot, package, owner), reserved_quantity in reserved_move_lines.items():
        if location.should_bypass_reservation() or\
            self.env['stock.quant']._should_bypass_product(product, location, reserved_quantity, lot, package, owner):
            continue
        else:
            self.env['stock.quant']._update_reserved_quantity(product, location, reserved_quantity, lot_id=lot, package_id=package, owner_id=owner)

protected Map<ProductLocationTrackingKey, StockLocationLine> buildTrackedMap(
    List<StockLocationLine> trackedSll) {
  Map<ProductLocationTrackingKey, StockLocationLine> map = new HashMap<>();
  if (CollectionUtils.isEmpty(trackedSll)) {
    return map;
  }
  for (StockLocationLine stockLocationLine : trackedSll) {
    Product product = stockLocationLine.getProduct();
    TrackingNumber trackingNumber = stockLocationLine.getTrackingNumber();
    StockLocation location = stockLocationLine.getDetailsStockLocation();
    if (product == null || trackingNumber == null || location == null) {
      continue;
    }
    map.put(
        ProductLocationTrackingKey.of(product.getId(), trackingNumber.getId(), location.getId()),
        stockLocationLine);
  }
  return map;
}

def get_available_qty_to_reserve(
	item_code: str, warehouse: str, batch_no: str | None = None, ignore_sre=None
) -> float:
	"""Returns `Available Qty to Reserve (Actual Qty - Reserved Qty)` for Item, Warehouse and Batch combination."""

	from erpnext.stock.doctype.batch.batch import get_batch_qty

	if batch_no:
		return get_batch_qty(
			item_code=item_code,
			warehouse=warehouse,
			batch_no=batch_no,
			ignore_voucher_nos=[ignore_sre] if ignore_sre else None,
		)

	available_qty = _get_stock_balance(item_code, warehouse)

	if available_qty:
		sre = frappe.qb.DocType("Stock Reservation Entry")
		query = (
			frappe.qb.from_(sre)
			.select(Sum(sre.reserved_qty - sre.delivered_qty - sre.transferred_qty - sre.consumed_qty))
			.where(
				(sre.docstatus == 1)
				& (sre.item_code == item_code)
				& (sre.warehouse == warehouse)
				& (sre.delivered_qty < sre.reserved_qty)
			)
			.for_update()
		)

		if ignore_sre:
			query = query.where(sre.name != ignore_sre)

		reserved_qty = query.run()[0][0] or 0.0

		if reserved_qty:
			return available_qty - reserved_qty

	return available_qty

@api.model
def _update_available_quantity(self, product_id, location_id, quantity=False, reserved_quantity=False, lot_id=None, package_id=None, owner_id=None, in_date=None):
    """ Increase or decrease `quantity` or 'reserved quantity' of a set of quants for a given set of
    product_id/location_id/lot_id/package_id/owner_id.

    :param product_id:
    :param location_id:
    :param quantity:
    :param lot_id:
    :param package_id:
    :param owner_id:
    :param datetime in_date: Should only be passed when calls to this method are done in
                             order to move a quant. When creating a tracked quant, the
                             current datetime will be used.
    :return: tuple (available_quantity, in_date as a datetime)
    """
    if not (quantity or reserved_quantity):
        raise ValidationError(_('Quantity or Reserved Quantity should be set.'))
    self = self.sudo()
    quants = self._gather(product_id, location_id, lot_id=lot_id, package_id=package_id, owner_id=owner_id, strict=True)
    if lot_id:
        if product_id.uom_id.compare(quantity, 0) > 0:
            quants = quants.filtered(lambda q: q.lot_id)
        else:
            # Don't remove quantity from a negative quant without lot
            quants = quants.filtered(lambda q: product_id.uom_id.compare(q.quantity, 0) > 0 or q.lot_id)

    if location_id.should_bypass_reservation():
        incoming_dates = []
    else:
        incoming_dates = [quant.in_date for quant in quants if quant.in_date and
                          quant.uom_id.compare(quant.quantity, 0) > 0]
    if in_date:
        incoming_dates += [in_date]
    # If multiple incoming dates are available for a given lot_id/package_id/owner_id, we
    # consider only the oldest one as being relevant.
    if incoming_dates:
        in_date = min(incoming_dates)
    else:
        in_date = fields.Datetime.now()

    quant = None
    if quants:
        # quants are already ordered in _gather
        # lock the first available
        quant = quants.try_lock_for_update(allow_referencing=True, limit=1)

    if quant:
        vals = {'in_date': in_date}
        if quantity:
            vals['quantity'] = quant.quantity + quantity
        if reserved_quantity:
            vals['reserved_quantity'] = max(0, quant.reserved_quantity + reserved_quantity)
        quant.write(vals)
    else:
        vals = {
            'product_id': product_id.id,
            'location_id': location_id.id,
            'lot_id': lot_id and lot_id.id,
            'package_id': package_id and package_id.id,
            'owner_id': owner_id and owner_id.id,
            'in_date': in_date,
        }
        if quantity:
            vals['quantity'] = quantity
        if reserved_quantity:
            vals['reserved_quantity'] = reserved_quantity
        self.create(vals)
    return self._get_available_quantity(product_id, location_id, lot_id=lot_id, package_id=package_id, owner_id=owner_id, strict=True, allow_negative=True), in_date

protected void updateReservedQty(
    StockLocationLine stockLocationLine, StockMoveLine stockMoveLine, BigDecimal newReservedQty)
    throws AxelorException {
  if (stockMoveLine.getProduct() == null || !stockMoveLine.getProduct().getStockManaged()) {
    return;
  }
  SaleOrderLine saleOrderLine = stockMoveLine.getSaleOrderLine();
  if (saleOrderLine != null) {
    updateReservedQty(saleOrderLine, newReservedQty);
  } else {
    checkBeforeUpdatingQties(stockMoveLine, newReservedQty);
    if (Beans.get(AppSupplychainService.class)
        .getAppSupplychain()
        .getBlockDeallocationOnAvailabilityRequest()) {
      checkAvailabilityRequest(stockMoveLine, newReservedQty, false);
    }
    if (stockMoveLine.getRequestedReservedQty().compareTo(newReservedQty) < 0
        && newReservedQty.compareTo(BigDecimal.ZERO) > 0) {
      updateRequestedReservedQty(stockLocationLine, stockMoveLine, newReservedQty);
      requestQty(stockMoveLine);
    }

    BigDecimal availableQtyToBeReserved =
        stockLocationLine.getCurrentQty().subtract(stockLocationLine.getReservedQty());
    BigDecimal diffReservedQuantity = newReservedQty.subtract(stockMoveLine.getReservedQty());
    Product product = stockMoveLine.getProduct();
    BigDecimal diffReservedQuantityLocation =
        convertUnitWithProduct(
            stockMoveLine.getUnit(), stockLocationLine.getUnit(), diffReservedQuantity, product);
    if (availableQtyToBeReserved.compareTo(diffReservedQuantityLocation) < 0) {
      throw new AxelorException(
          TraceBackRepository.CATEGORY_INCONSISTENCY,
          I18n.get(SupplychainExceptionMessage.SALE_ORDER_LINE_QTY_NOT_AVAILABLE));
    }
    stockMoveLine.setReservedQty(newReservedQty);

    // update in stock location line
    updateReservedQty(stockLocationLine);
  }
}

