def _get_available_quantity(self, product_id, location_id, lot_id=None, package_id=None, owner_id=None, strict=False, allow_negative=False):
    """ Return the available quantity, i.e. the sum of `quantity` minus the sum of
    `reserved_quantity`, for the set of quants sharing the combination of `product_id,
    location_id` if `strict` is set to False or sharing the *exact same characteristics*
    otherwise.
    The set of quants to filter from can be in `self`, if not a search will be done
    This method is called in the following usecases:
        - when a stock move checks its availability
        - when a stock move actually assign
        - when editing a move line, to check if the new value is forced or not
        - when validating a move line with some forced values and have to potentially unlink an
          equivalent move line in another picking
    In the two first usecases, `strict` should be set to `False`, as we don't know what exact
    quants we'll reserve, and the characteristics are meaningless in this context.
    In the last ones, `strict` should be set to `True`, as we work on a specific set of
    characteristics.

    :return: available quantity as a float
    """
    self = self.sudo()
    quants = self._gather(product_id, location_id, lot_id=lot_id, package_id=package_id, owner_id=owner_id, strict=strict)
    if not product_id.tracking:
        available_quantity = sum(quants.mapped('quantity')) - sum(quants.mapped('reserved_quantity'))
        if allow_negative:
            return available_quantity
        else:
            return available_quantity if product_id.uom_id.compare(available_quantity, 0.0) >= 0.0 else 0.0
    else:
        availaible_quantities = {lot_id: 0.0 for lot_id in list(set(quants.mapped('lot_id'))) + ['untracked']}
        for quant in quants:
            if not quant.lot_id and strict and lot_id:
                continue
            if not quant.lot_id:
                availaible_quantities['untracked'] += quant.quantity - quant.reserved_quantity
            else:
                availaible_quantities[quant.lot_id] += quant.quantity - quant.reserved_quantity
        if allow_negative:
            return sum(availaible_quantities.values())
        else:
            return sum(available_quantity for available_quantity in availaible_quantities.values() if product_id.uom_id.compare(available_quantity, 0) > 0)

@fields.depends('expected_quantity', 'inventory',
    '_parent_inventory.company',
    methods=['on_change_with_quantity_variation'])
def on_change_with_tolerance_quantity_variation(self, name=None):
    if self.inventory:
        pool = Pool()
        Configuration = pool.get('stock.configuration')
        config = Configuration(1)
        quantity_tolerance = config.get_multivalue(
            'inventory_quantity_tolerance',
            company=self.inventory.company.id)
        quantity_variation = self.on_change_with_quantity_variation()
        percentage = None
        if self.expected_quantity and quantity_variation is not None:
            percentage = abs(quantity_variation) / self.expected_quantity
        if quantity_tolerance and percentage is not None:
            return round(
                percentage / quantity_tolerance,
                self.__class__.tolerance_quantity_variation.digits[1])

protected void checkMissingStockLocation(Inventory inventory) throws AxelorException {

  List<InventoryLine> inventoryLinesWithMissingStockLocation =
      inventoryLineRepository
          .all()
          .filter("self.inventory = :inventory and self.stockLocation is null")
          .bind("inventory", inventory)
          .fetch(
              INVENTORY_LINE_WITHOUT_STOCK_LOCATION_DISPLAY_LIMIT
                  + 1); // Fetch limit + 1 to check for excess items

  if (CollectionUtils.isEmpty(inventoryLinesWithMissingStockLocation)) {
    return;
  }

  StringHtmlListBuilder stringHTMLListInventoryLine = new StringHtmlListBuilder();
  inventoryLinesWithMissingStockLocation.stream()
      .forEach(
          inventoryLine -> {
            if (inventoryLine.getTrackingNumber() == null) {
              stringHTMLListInventoryLine.append(inventoryLine.getProduct().getFullName());
            } else {
              stringHTMLListInventoryLine.append(
                  String.format(
                      "%s : %s",
                      inventoryLine.getProduct().getFullName(),
                      inventoryLine.getTrackingNumber().getTrackingNumberSeq()));
            }
          });

  if (inventoryLinesWithMissingStockLocation.size()
      > INVENTORY_LINE_WITHOUT_STOCK_LOCATION_DISPLAY_LIMIT) {
    stringHTMLListInventoryLine.append("...");
  }

  throw new AxelorException(
      TraceBackRepository.CATEGORY_NO_VALUE,
      String.format(
          I18n.get(StockExceptionMessage.INVENTORY_LINE_STOCK_LOCATION_MISSING),
          stringHTMLListInventoryLine));
}
